import json
# rule: for each maximal same-color diagonal chain, extend along its diagonal toward the open side until edge/non-bg
def f(g):
    h,w=len(g),len(g[0]); bg=g[0][0]
    seen=[[False]*w for _ in range(h)]; res=[r[:] for r in g]
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bg and not seen[r][c]:
                col=g[r][c]; stack=[(r,c)]; seen[r][c]=True; chain=[]
                while stack:
                    a,b=stack.pop(); chain.append((a,b))
                    for da,db in [(1,1),(-1,-1),(1,-1),(-1,1)]:
                        nr,nc=a+da,b+db
                        if 0<=nr<h and 0<=nc<w and g[nr][nc]==col and not seen[nr][nc]:
                            seen[nr][nc]=True; stack.append((nr,nc))
                if len(chain)<2: continue
                chain.sort()
                # direction: diagonal line through chain
                d=(chain[-1][0]-chain[0][0], chain[-1][1]-chain[0][1])
                s=1 if d[0]>0 else -1
                d=(d[0]*s//abs(d[0]) if d[0] else 0, d[1]*s//abs(d[1]) if d[1] else 0)
                if d==(0,0): continue
                ends=[(chain[0][0]-s,d[0],d[1]),(chain[-1][0]+s,d[0],d[1])]
                best=None
                for start,_dd,dd in ends:
                    count=0
                    rr,cc=start; 
                    while True:
                        rr,cc=rr+_dd,cc+dd
                        if 0<=rr<h and 0<=cc<w and g[rr][cc]==bg: count+=1
                        else: break
                    if best is None or count>best[0]: best=(count,start,_dd,dd)
                if best is None: continue
                _,start,dr,dc=best
                rr,cc=start; n=0
                while 0<=rr<h and 0<=cc<w and g[rr][cc]==bg:
                    res[rr][cc]=col; rr,cc=rr+dr,cc+dc; n+=1
    return res
